import{_ as d,o as e,c as o,a2 as p}from"./chunks/framework.Bg-Zxr5O.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/DESCRIPTIVES.md","filePath":"manual-zh/DESCRIPTIVES.md","lastUpdated":1785684581000}'),c={name:"manual-zh/DESCRIPTIVES.md"};function r(s,t,a,i,S,n){return e(),o("div",null,[...t[0]||(t[0]=[p(`<h3 id="_15-1-descriptives" tabindex="-1">15.1 DESCRIPTIVES <a class="header-anchor" href="#_15-1-descriptives" aria-label="Permalink to &quot;15.1 DESCRIPTIVES&quot;">​</a></h3><pre><code>DESCRIPTIVES
        /VARIABLES=var_list
        /MISSING={VARIABLE,LISTWISE} {INCLUDE,NOINCLUDE}
        /FORMAT={LABELS,NOLABELS} {NOINDEX,INDEX} {LINE,SERIAL}
        /SAVE
        /STATISTICS={ALL,MEAN,SEMEAN,STDDEV,VARIANCE,KURTOSIS,
                     SKEWNESS,RANGE,MINIMUM,MAXIMUM,SUM,DEFAULT,
                     SESKEWNESS,SEKURTOSIS}
        /SORT={NONE,MEAN,SEMEAN,STDDEV,VARIANCE,KURTOSIS,SKEWNESS,
               RANGE,MINIMUM,MAXIMUM,SUM,SESKEWNESS,SEKURTOSIS,NAME}
              {A,D}
</code></pre><p><code>DESCRIPTIVES</code> 规程读取活动数据集，并输出用户所请求的线性描述性统计量。此外，它还可以选择性地计算 Z 分数。</p><p><code>VARIABLES</code> 子命令是必需的，它指定要分析的变量列表。关键字 <code>VARIABLES</code> 是可选的。</p><p>所有其他子命令都是可选的：</p><p><code>MISSING</code> 子命令决定对缺失变量的处理。如果设置为 <code>INCLUDE</code>，则用户缺失值被包含在计算中。如果设置为 <code>NOINCLUDE</code>（默认值），则用户缺失值被排除。如果设置为 <code>VARIABLE</code>，则缺失值按变量逐个排除；如果设置为 <code>LISTWISE</code>，则只要该个案中任何值为系统缺失（或在 <code>INCLUDE</code> 设置时为用户缺失）值，整个个案就被排除。</p><p><code>FORMAT</code> 子命令没有效果。接受它是为了向后兼容。</p><p><code>SAVE</code> 子命令使 <code>DESCRIPTIVES</code> 为所有指定变量计算 Z 分数。这些 Z 分数被保存到新变量中。变量名的生成方式是：先尝试原变量名前加 Z 并截断到最多 8 个字符，然后依次尝试 ZSC000 到 ZSC999、STDZ00 到 STDZ09、ZZZZ00 到 ZZZZ09、ZQZQ00 到 ZQZQ09。此外，也可以在变量列表的 <code>VARIABLES</code> 上，通过在每个变量后加括号来显式指定 Z 分数变量名。计算 Z 分数时，PSPP 忽略 <code>TEMPORARY</code>，将临时变化视为永久。</p><p><code>STATISTICS</code> 子命令指定要显示的统计量：</p><p><code>ALL</code></p><p>以下所有统计量。</p><p><code>MEAN</code></p><p>算术平均值。</p><p><code>SEMEAN</code></p><p>均值的标准误。</p><p><code>STDDEV</code></p><p>标准差。</p><p><code>VARIANCE</code></p><p>方差。</p><p><code>KURTOSIS</code></p><p>峰度及峰度的标准误。</p><p><code>SKEWNESS</code></p><p>偏度及偏度的标准误。</p><p><code>RANGE</code></p><p>极差。</p><p><code>MINIMUM</code></p><p>最小值。</p><p><code>MAXIMUM</code></p><p>最大值。</p><p><code>SUM</code></p><p>总和。</p><p><code>DEFAULT</code></p><p>均值、均值的标准差、最小值、最大值。</p><p><code>SEKURTOSIS</code></p><p>峰度的标准误。</p><p><code>SESKEWNESS</code></p><p>偏度的标准误。</p><p><code>SORT</code> 子命令指定统计量应如何排序。大多数可能的值应当不言自明。<code>NAME</code> 使统计量按名称排序。默认情况下，统计量按它们在 <code>VARIABLES</code> 子命令上指定的顺序列出。<code>A</code> 和 <code>D</code> 设置分别要求升序或降序排序。</p><h4 id="_15-1-1-descriptives-示例" tabindex="-1">15.1.1 Descriptives 示例 <a class="header-anchor" href="#_15-1-1-descriptives-示例" aria-label="Permalink to &quot;15.1.1 Descriptives 示例&quot;">​</a></h4><p>physiology.sav 文件包含一组样本人群的多种生理数据。对变量 <strong>height</strong> 和 <strong>temperature</strong> 运行 <code>DESCRIPTIVES</code> 命令并使用默认选项，可以查看这两个变量的简单线性统计量。在示例 15.1 中，这些变量在 <code>VARIABLES</code> 子命令上指定，并使用了 <code>SAVE</code> 选项，以请求计算 Z 分数。</p><p>命令完成后，本示例再次运行 <code>DESCRIPTIVES</code>，这次针对 <strong>zheight</strong> 和 <strong>ztemperature</strong> 变量，它们是由第一个 <code>DESCRIPTIVES</code> 命令生成的两个归一化（Z 分数）变量。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;physiology.sav&#39;.  descriptives         /variables = height temperature         /save.  descriptives         /variables = zheight ztemperature.</span></span></code></pre></div><p><strong>示例 15.1：</strong> 运行两个 <code>DESCRIPTIVES</code> 命令，其中一个带有 <code>SAVE</code> 子命令</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>截图 15.1：</strong> 选入了两个变量及 Z 分数选项的 Descriptives 对话框</p><p>在结果 15.1 中，我们可以看到每个变量都有 40 个有效数据，且没有缺失值。height 和 temperature 的均值分别为 16677.12 和 37.02。temperature 的描述性统计量看起来是合理的。但 <strong>height</strong> 的标准差异常高，最小值也低得可疑。这是由于数据中的一个录入错误（参见 <a href="./Identifying-incorrect-data">识别不正确的数据</a>）所致。</p><p>在第二个 Descriptive Statistics 命令中，可以看到两个 Z 分数变量的均值和标准差分别为 0 和 1。所有 Z 分数统计量都应具有这些性质，因为它们是原始分数的归一化版本。</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>Mean</th><th>Std Dev</th><th>Minimum</th><th>Maximum</th></tr></thead><tbody><tr><td>Source</td><td>Target</td><td></td><td></td><td></td><td></td></tr><tr><td>Height in millimeters</td><td>Zheight</td><td></td><td></td><td></td><td></td></tr><tr><td>Internal body temperature in degrees Celcius</td><td>Ztemperature</td><td></td><td></td><td></td><td></td></tr><tr><td>Height in millimeters</td><td>40</td><td>1677.12</td><td>262.87</td><td>179</td><td>1903</td></tr><tr><td>Internal body temperature in degrees Celcius</td><td>40</td><td>37.02</td><td>1.82</td><td>32.59</td><td>39.97</td></tr><tr><td>Valid N (listwise)</td><td>40</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>N</td><td>Mean</td><td>Std Dev</td><td>Minimum</td><td>Maximum</td></tr><tr><td>Z-score of Height in millimeters</td><td>40</td><td>1.93E-015</td><td>1.00</td><td>-5.70</td><td>.86</td></tr><tr><td>Z-score of Internal body temperature in degrees Celcius</td><td>40</td><td>1.37E-015</td><td>1.00</td><td>-2.44</td><td>1.62</td></tr><tr><td>Valid N (listwise)</td><td>40</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>结果 15.1：</strong> 包含两个归一化变量（Z 分数）的描述性统计量</p>`,49)])])}const l=d(c,[["render",r]]);export{I as __pageData,l as default};
